import{_ as e,a as o,o as a,a6 as r}from"./chunks/framework.CJDy2q7X.js";const u=JSON.parse('{"title":"Customer","description":"","frontmatter":{"outline":false,"apiType":"rest"},"headers":[],"relativePath":"api/rest-api/shop/customers/index.md","filePath":"api/rest-api/shop/customers/index.md","lastUpdated":1787290888000}'),s={name:"api/rest-api/shop/customers/index.md"};function d(i,t,h,n,c,p){return a(),o("div",null,t[0]||(t[0]=[r('<h1 id="customer" tabindex="-1">Customer <a class="header-anchor" href="#customer" aria-label="Permalink to &quot;Customer&quot;">​</a></h1><p>The Customer menu is the shopper&#39;s account surface — everything tied to a registered customer: signing up and in, managing the profile and saved addresses, and reading their order history, invoices, downloadable products and reviews.</p><h2 id="authentication" tabindex="-1">Authentication <a class="header-anchor" href="#authentication" aria-label="Permalink to &quot;Authentication&quot;">​</a></h2><p>Registration, login and forgot-password are reached with the storefront key alone. Everything else here acts on a specific customer&#39;s data and requires that customer to be authenticated — log in to obtain a customer Bearer token, then send it on every account request. A customer can only ever see and act on their own data.</p><h2 id="how-a-client-uses-this" tabindex="-1">How a client uses this <a class="header-anchor" href="#how-a-client-uses-this" aria-label="Permalink to &quot;How a client uses this&quot;">​</a></h2><p>A typical flow is: <strong>register</strong> (or <strong>login</strong>) to obtain a token, <strong>verify the token</strong> when resuming a session, manage the <strong>profile</strong> and <strong>addresses</strong>, and read back <strong>orders</strong>, <strong>invoices</strong>, <strong>downloadable products</strong> and <strong>reviews</strong>. Logout invalidates the token; forgot/change password handle credential recovery and rotation.</p><h2 id="operations-in-this-menu" tabindex="-1">Operations in this menu <a class="header-anchor" href="#operations-in-this-menu" aria-label="Permalink to &quot;Operations in this menu&quot;">​</a></h2><h3 id="registration-session" tabindex="-1">Registration &amp; session <a class="header-anchor" href="#registration-session" aria-label="Permalink to &quot;Registration &amp; session&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Operation</th><th>Method &amp; Path</th><th>Description</th></tr></thead><tbody><tr><td><a href="/api/rest-api/shop/customers/customer-registration.html">Registration</a></td><td><code>POST /api/shop/customers</code></td><td>Create a new customer account.</td></tr><tr><td><a href="/api/rest-api/shop/customers/customer-login.html">Login</a></td><td><code>POST /api/shop/customer/login</code></td><td>Authenticate and receive a Bearer token.</td></tr><tr><td><a href="/api/rest-api/shop/customers/customer-verify-token.html">Verify Token</a></td><td><code>POST /api/shop/verify-tokens</code></td><td>Check that a customer token is still valid.</td></tr><tr><td><a href="/api/rest-api/shop/customers/customer-logout.html">Customer Logout</a></td><td><code>POST /api/shop/customer/logout</code></td><td>Invalidate the current token.</td></tr><tr><td><a href="/api/rest-api/shop/customers/forgot-password.html">Forgot Password</a></td><td><code>POST /api/shop/forgot-passwords</code></td><td>Send a password-reset email.</td></tr><tr><td><a href="/api/rest-api/shop/customers/change-password.html">Change Password</a></td><td><code>PUT /api/shop/customer-profile-updates/{id}</code></td><td>Change the customer&#39;s password.</td></tr></tbody></table><h3 id="profile" tabindex="-1">Profile <a class="header-anchor" href="#profile" aria-label="Permalink to &quot;Profile&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Operation</th><th>Method &amp; Path</th><th>Description</th></tr></thead><tbody><tr><td><a href="/api/rest-api/shop/customers/get-customer-profile.html">Get Profile</a></td><td><code>GET /api/shop/customer-profile</code></td><td>Read the authenticated customer&#39;s profile.</td></tr><tr><td><a href="/api/rest-api/shop/customers/update-customer-profile.html">Update Profile</a></td><td><code>PUT /api/shop/customer-profile-updates/{id}</code></td><td>Update profile details.</td></tr><tr><td><a href="/api/rest-api/shop/customers/delete-customer-profile.html">Delete Profile</a></td><td><code>POST /api/shop/customer-profile-deletes/{id}</code></td><td>Delete the customer account.</td></tr></tbody></table><h3 id="addresses" tabindex="-1">Addresses <a class="header-anchor" href="#addresses" aria-label="Permalink to &quot;Addresses&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Operation</th><th>Method &amp; Path</th><th>Description</th></tr></thead><tbody><tr><td><a href="/api/rest-api/shop/customers/get-customer-addresses.html">Get Addresses</a></td><td><code>GET /api/shop/customer-addresses</code></td><td>List the customer&#39;s saved addresses.</td></tr><tr><td><a href="/api/rest-api/shop/customers/create-customer-address.html">Create Address</a></td><td><code>POST /api/shop/customer-addresses</code></td><td>Add a new address.</td></tr><tr><td><a href="/api/rest-api/shop/customers/update-customer-address.html">Update Address</a></td><td><code>PUT /api/shop/customer-addresses/{id}</code></td><td>Edit an address.</td></tr><tr><td><a href="/api/rest-api/shop/customers/delete-customer-address.html">Delete Address</a></td><td><code>DELETE /api/shop/customer-addresses/{id}</code></td><td>Remove an address.</td></tr></tbody></table><h3 id="orders" tabindex="-1">Orders <a class="header-anchor" href="#orders" aria-label="Permalink to &quot;Orders&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Operation</th><th>Method &amp; Path</th><th>Description</th></tr></thead><tbody><tr><td><a href="/api/rest-api/shop/customer-orders/get-customer-orders.html">Get Orders</a></td><td><code>GET /api/shop/customer-orders</code></td><td>List the customer&#39;s orders.</td></tr><tr><td><a href="/api/rest-api/shop/customer-orders/get-customer-order.html">Get Order</a></td><td><code>GET /api/shop/customer-orders/{id}</code></td><td>A single order with its detail.</td></tr></tbody></table><h3 id="invoices" tabindex="-1">Invoices <a class="header-anchor" href="#invoices" aria-label="Permalink to &quot;Invoices&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Operation</th><th>Method &amp; Path</th><th>Description</th></tr></thead><tbody><tr><td><a href="/api/rest-api/shop/customer-invoices/get-customer-invoices.html">Get Invoices</a></td><td><code>GET /api/shop/customer-invoices</code></td><td>List the customer&#39;s invoices.</td></tr><tr><td><a href="/api/rest-api/shop/customer-invoices/get-customer-invoice.html">Get Invoice</a></td><td><code>GET /api/shop/customer-invoices/{id}</code></td><td>A single invoice.</td></tr><tr><td><a href="/api/rest-api/shop/customer-invoices/download-customer-invoice-pdf.html">Download Invoice PDF</a></td><td><code>GET /api/shop/customer-invoices/{id}/pdf</code></td><td>Download the invoice as a PDF.</td></tr></tbody></table><h3 id="downloadable-products" tabindex="-1">Downloadable products <a class="header-anchor" href="#downloadable-products" aria-label="Permalink to &quot;Downloadable products&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Operation</th><th>Method &amp; Path</th><th>Description</th></tr></thead><tbody><tr><td><a href="/api/rest-api/shop/customer-downloadable-products/get-customer-downloadable-products.html">Get Downloadable Products</a></td><td><code>GET /api/shop/customer-downloadable-products</code></td><td>List the customer&#39;s purchased downloads.</td></tr><tr><td><a href="/api/rest-api/shop/customer-downloadable-products/get-customer-downloadable-product.html">Get Downloadable Product</a></td><td><code>GET /api/shop/customer-downloadable-products/{id}</code></td><td>A single downloadable purchase.</td></tr></tbody></table><h3 id="reviews" tabindex="-1">Reviews <a class="header-anchor" href="#reviews" aria-label="Permalink to &quot;Reviews&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Operation</th><th>Method &amp; Path</th><th>Description</th></tr></thead><tbody><tr><td><a href="/api/rest-api/shop/customer-reviews/get-customer-reviews.html">Get Customer Reviews</a></td><td><code>GET /api/shop/customer-reviews</code></td><td>List the reviews the customer has written.</td></tr><tr><td><a href="/api/rest-api/shop/customer-reviews/get-customer-review.html">Get Customer Review</a></td><td><code>GET /api/shop/customer-reviews/{id}</code></td><td>A single review by the customer.</td></tr></tbody></table><p>Registration, login and forgot-password need only the storefront key; every other Customer endpoint requires a customer Bearer token — see <a href="/api/rest-api/authentication.html">Authentication</a>.</p>',22)]))}const m=e(s,[["render",d]]);export{u as __pageData,m as default};
